#!/usr/bin/env bash
# Fail when a commit of the given revision range carries agent attribution.
# Usage: check_attribution.sh <rev-range>   (e.g. "$BASE..$HEAD", or "$SHA^!" for one commit)
set -euo pipefail

range="${1:?usage: check_attribution.sh <rev-range>}"

message_re='co-authored-by:|claude-session:|\bgenerated with|\bgenerated by \[?claude|anthropic\.com'
email_re='anthropic\.com'
name_re='^claude'

checked=0
bad=0
while read -r sha; do
  checked=$((checked + 1))
  hit=""
  line="$(git log -1 --format=%B "$sha" | grep -iE -m1 -- "$message_re" || true)"
  if [ -n "$line" ]; then
    hit="$line"
  else
    for ident in "$(git log -1 --format='%an <%ae>' "$sha")" "$(git log -1 --format='%cn <%ce>' "$sha")"; do
      name="${ident%% <*}"
      email="${ident##*<}"
      if printf '%s' "$email" | grep -qiE -- "$email_re" || printf '%s' "$name" | grep -qiE -- "$name_re"; then
        hit="identity: $ident"
        break
      fi
    done
  fi
  if [ -n "$hit" ]; then
    bad=$((bad + 1))
    echo "agent attribution in $(git log -1 --format='%h %s' "$sha")"
    echo "  matched: $hit"
  fi
done < <(git rev-list "$range")

if [ "$bad" -gt 0 ]; then
  echo "$bad of $checked commit(s) carry agent attribution"
  exit 1
fi
echo "checked $checked commit(s): no agent attribution"
